// Deduplicate and extract email bodies
const items = $input.all();
const seen = new Set();
const result = [];

for (const item of items) {
  const msg = item.json;
  const subject = msg.subject || '';
  const from = msg.from || '';
  const body = msg.text || msg.html || '';

  const key = subject.toLowerCase().trim();
  if (seen.has(key)) continue;
  seen.add(key);

  // Filter relevant emails
  const relevant = [
    'internship', 'intern', 'opportunity', 'job', 'hiring', 'role',
    'engineer', 'researcher', 'analyst', 'quant'
  ];
  const text = (subject + ' ' + body).toLowerCase();
  if (!relevant.some(kw => text.includes(kw))) continue;

  result.push({
    subject,
    from,
    body: body.substring(0, 3000), // Limit for Claude
    date: msg.date || new Date().toISOString()
  });
}

return result.map(r => ({ json: r }));

