// Parse Claude response and score listings
const items = $input.all();
const USER_SKILLS = [
  'python', 'pytorch', 'tensorflow', 'langchain', 'fastapi', 'react',
  'docker', 'aws', 'supabase', 'redis', 'ml', 'ai', 'machine learning',
  'computer vision', 'rag', 'llm', 'diffusion', 'transformer', 'c++', 'java'
];

const result = [];

for (const item of items) {
  const content = item.json?.content?.[0]?.text || '';
  let listings = [];

  try {
    const jsonMatch = content.match(/\[.*\]/s);
    if (jsonMatch) listings = JSON.parse(jsonMatch[0]);
  } catch (e) { continue; }

  for (const listing of listings) {
    // Score against user skills
    const skills = (listing.skills_required || []).map(s => s.toLowerCase());
    const matched = skills.filter(s => USER_SKILLS.some(us => s.includes(us) || us.includes(s)));
    const matchScore = Math.min(100, Math.round((matched.length / Math.max(skills.length, 1)) * 100));

    // Calculate days until deadline
    let daysUntilDeadline = null;
    if (listing.deadline) {
      const diff = new Date(listing.deadline) - new Date();
      daysUntilDeadline = Math.ceil(diff / (1000 * 60 * 60 * 24));
    }

    result.push({
      json: {
        ...listing,
        match_score: matchScore,
        days_until_deadline: daysUntilDeadline,
        status: 'saved',
        is_new: true,
        scan_id: $('Webhook Trigger').first()?.json?.body?.scan_id || null,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      }
    });
  }
}

return result;
